fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider
    let participants_to_consider = std::cmp::min(n as usize, participations.len());
    
    // Count eligible participants
    let mut eligible_count = 0;
    for i in 0..participants_to_consider {
        let attendance = participations[i];
        // Check: 5 - attendance >= k
        if 5 - attendance >= k {
            eligible_count += 1;
        }
    }
    
    // Maximum number of teams = floor(eligible_count / 3)
    eligible_count / 3
}